#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_push_pop() {
        let mut s: Stack<i32> = Stack::new();
        s.push(1);
        s.push(2);
        s.push(3);
        assert_eq!(s.pop(), Some(3));
        assert_eq!(s.pop(), Some(2));
        assert_eq!(s.pop(), Some(1));
        assert_eq!(s.pop(), None);
    }

    #[test]
    fn test_peek() {
        let mut s: Stack<i32> = Stack::new();
        assert_eq!(s.peek(), None);
        s.push(42);
        assert_eq!(s.peek(), Some(&42));
        assert_eq!(s.size(), 1); // peek didn't remove
    }

    #[test]
    fn test_size_and_is_empty() {
        let mut s: Stack<&str> = Stack::new();
        assert!(s.is_empty());
        assert_eq!(s.size(), 0);
        s.push("a");
        s.push("b");
        assert!(!s.is_empty());
        assert_eq!(s.size(), 2);
    }

    #[test]
    fn test_from_vec() {
        let s: Stack<i32> = Stack::from(vec![1, 2, 3]);
        // last element (3) should be the top
        let mut s = s;
        assert_eq!(s.pop(), Some(3));
        assert_eq!(s.pop(), Some(2));
        assert_eq!(s.pop(), Some(1));
    }
}
